import{_ as t,o as r,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-09-10","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-09-10","date":"2025-09-10T00:00:00.000Z","updated":"2025-09-15T00:00:00.000Z","tags":["Ceph","Distributed Storage","Release Planning","RGW","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-10.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-10.md","lastUpdated":1780460162000}'),l={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-10.md"};function n(i,a,s,g,h,d){return r(),e("div",null,[...a[0]||(a[0]=[o('<h3 id="ceph-社区会议纪要-版本规划讨论" tabindex="-1"><strong>Ceph 社区会议纪要 - 版本规划讨论</strong> <a class="header-anchor" href="#ceph-社区会议纪要-版本规划讨论" aria-label="Permalink to &quot;**Ceph 社区会议纪要 - 版本规划讨论**&quot;">​</a></h3><h4 id="会议概览" tabindex="-1"><strong>会议概览</strong> <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;**会议概览**&quot;">​</a></h4><p>本次会议主要围绕 Ceph Umbrella 版本的规划进行讨论，涵盖了多个关键功能的开发进度、优先级和未来计划。会议重点关注了 D4N、DDUP、快照、S3 功能增强等核心议题，并明确了部分功能的预期交付时间。</p><h4 id="关键讨论议题" tabindex="-1"><strong>关键讨论议题</strong> <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;**关键讨论议题**&quot;">​</a></h4><h4 id="_1-d4n-分布式数据驱动网络" tabindex="-1"><strong>1. D4N（分布式数据驱动网络）</strong> <a class="header-anchor" href="#_1-d4n-分布式数据驱动网络" aria-label="Permalink to &quot;**1. D4N（分布式数据驱动网络）**&quot;">​</a></h4><ul><li><strong>当前状态</strong>：Pria 正在进行性能优化工作，预计这些改进将包含在 Umbrella 版本中。</li><li><strong>下一步计划</strong>：实现分布式缓存，这是下一个重要的 MVP。</li><li><strong>进展</strong>：目前仅支持单节点缓存，未来将扩展为分布式架构。</li></ul><h4 id="_2-ddup-去重" tabindex="-1"><strong>2. DDUP（去重）</strong> <a class="header-anchor" href="#_2-ddup-去重" aria-label="Permalink to &quot;**2. DDUP（去重）**&quot;">​</a></h4><ul><li><strong>最新进展</strong>：Full DDUP PR 已提交并处于测试阶段，预计很快合并。Rate Limiting 功能也已开发完成，待文档审核后合并。Small Object Dedup 正在开发中，预计会在 Umbrella 版本中提供。</li><li><strong>用户收益</strong>：功能可同时显示标准对象去重和小对象去重的节省空间，帮助用户评估是否启用小对象去重。</li></ul><h4 id="_3-快照" tabindex="-1"><strong>3. 快照</strong> <a class="header-anchor" href="#_3-快照" aria-label="Permalink to &quot;**3. 快照**&quot;">​</a></h4><ul><li><strong>现状</strong>：目前无人全职负责，代码需 rebase 并修复单元测试，需进行回归测试，确保不影响版本控制功能。</li><li><strong>潜在价值</strong>：快照不仅适用于备份场景，还可能支持其他用例。</li></ul><h4 id="_4-有序桶列表" tabindex="-1"><strong>4. 有序桶列表</strong> <a class="header-anchor" href="#_4-有序桶列表" aria-label="Permalink to &quot;**4. 有序桶列表**&quot;">​</a></h4><ul><li><strong>进展</strong>：Eric 和 Matt 正在推进，但目前缺乏公开的设计文档或代码更新。</li></ul><h4 id="_5-客户管理策略" tabindex="-1"><strong>5. 客户管理策略</strong> <a class="header-anchor" href="#_5-客户管理策略" aria-label="Permalink to &quot;**5. 客户管理策略**&quot;">​</a></h4><ul><li><strong>状态</strong>：Pritha 和 Raja 正在开发相关 API，进展顺利，预计可按时交付。</li></ul><h4 id="_6-aws-组织-api" tabindex="-1"><strong>6. AWS 组织 API</strong> <a class="header-anchor" href="#_6-aws-组织-api" aria-label="Permalink to &quot;**6. AWS 组织 API**&quot;">​</a></h4><ul><li><strong>计划</strong>：扩展 Account Quota 和 Service Control Policies 功能，支持多级账户管理，目前处于设计阶段。</li></ul><h4 id="_7-s3-vectors" tabindex="-1"><strong>7. S3 Vectors</strong> <a class="header-anchor" href="#_7-s3-vectors" aria-label="Permalink to &quot;**7. S3 Vectors**&quot;">​</a></h4><ul><li><strong>现状</strong>：仍处于设计阶段，目标是在后续版本中提供基础 API。</li></ul><h4 id="_8-桶日志" tabindex="-1"><strong>8. 桶日志</strong> <a class="header-anchor" href="#_8-桶日志" aria-label="Permalink to &quot;**8. 桶日志**&quot;">​</a></h4><ul><li><strong>新增功能</strong>：Nitia 正在开发 EC Pools 支持，需改为异步刷新临时日志，预计在 New 版本中落地。</li></ul><h4 id="其他重要讨论" tabindex="-1"><strong>其他重要讨论</strong> <a class="header-anchor" href="#其他重要讨论" aria-label="Permalink to &quot;**其他重要讨论**&quot;">​</a></h4><h4 id="omap-data-logs-弃用" tabindex="-1"><strong>OMAP Data Logs 弃用</strong> <a class="header-anchor" href="#omap-data-logs-弃用" aria-label="Permalink to &quot;**OMAP Data Logs 弃用**&quot;">​</a></h4><ul><li>社区提议在 Umbrella 版本中标记 OMAP Data Logs 为弃用，为用户提供迁移时间。</li></ul><h4 id="版本发布计划" tabindex="-1"><strong>版本发布计划</strong> <a class="header-anchor" href="#版本发布计划" aria-label="Permalink to &quot;**版本发布计划**&quot;">​</a></h4><ul><li><strong>Tentacle RC1</strong> 已发布，正在收集用户反馈，可能需进一步修复后再发布正式版。</li><li><strong>Umbrella 版本优先级</strong>：确定包含 D4N 优化、Full DDUP、Small Object Dedup。待定：快照、有序桶列表。排除：S3 Vectors、Host Offload。</li></ul><h4 id="社区协作建议" tabindex="-1"><strong>社区协作建议</strong> <a class="header-anchor" href="#社区协作建议" aria-label="Permalink to &quot;**社区协作建议**&quot;">​</a></h4><ul><li>通过 EtherPad 或邮件列表公开功能规划，鼓励更多开发者参与讨论和贡献。</li></ul><h4 id="后续行动计划" tabindex="-1"><strong>后续行动计划</strong> <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;**后续行动计划**&quot;">​</a></h4><ul><li><strong>D4N</strong>：Pria 完成性能优化后提交代码。</li><li><strong>DDUP</strong>：合并 Full DDUP 和 Rate Limiting PR，推进 Small Object Dedup 开发。</li><li><strong>快照</strong>：寻找开发者负责 rebase 和测试。</li><li><strong>有序桶列表</strong>：联系 Eric/Matt 获取进展更新。</li><li><strong>OMAP 弃用</strong>：发布公告并更新文档。</li><li><strong>社区沟通</strong>：将功能列表通过邮件公开，征求社区意见。</li></ul><h4 id="保留关键词-中英对照" tabindex="-1"><strong>保留关键词（中英对照）</strong> <a class="header-anchor" href="#保留关键词-中英对照" aria-label="Permalink to &quot;**保留关键词（中英对照）**&quot;">​</a></h4><ul><li>Ceph, distributed storage, CRUSH algorithm, OSD, RADOS, PG, replication, erasure coding (EC), snapshots, versioning, S3 API, bucket logging, deduplication (DDUP), performance tuning.</li></ul>',31)])])}const _=t(l,[["render",n]]);export{c as __pageData,_ as default};
